import { Card } from 'antd'
import React, { Component } from 'react'
import { connect } from 'react-redux'
import moment from 'moment'
import { get } from 'lodash'

import { Filters, OverallRating, StatusWiseRating } from './components'
import { CustomerFeedbackStyle } from './index.style'
import policyActions from '../../../redux/policy/action'
import claimActions from '../../../redux/claims/actions'

const { getPartnersList, getProductsList } = policyActions
const { getFeedbackDashboardData } = claimActions

class CustomerFeedback extends Component {
  state = {
    filterValues: {}
  }

  componentDidMount() {
    const {location} = this.props;

    this.props.getPartnersList()
    this.props.getProductsList()
    this.fetch({
      startDate: get(location, 'state.startDate') || moment().clone().subtract(7, 'days').format('YYYY-MM-DD'),
      endDate: get(location, 'state.endDate') || moment().format('YYYY-MM-DD'),
      partners: get(location, 'state.partners'),
      productKey: get(location, 'state.productKey'),
      rating: get(location, 'state.rating')
    })
  }

  fetch = (values) => {
    this.setState({ filterValues: values })
    const { startDate, endDate, partners, productKey, rating } = values;
    this.props.getFeedbackDashboardData({
      query: {
        start_date: startDate,
        end_date: endDate,
        partners: partners,
        product_key: productKey,
        rating: rating
      }
    })
  }

  render() {
    const { history, location } = this.props
    const { filterValues } = this.state

    return (
      <CustomerFeedbackStyle>
        <Card>
          <Filters
            fetch={this.fetch}
            startDate={get(location, 'state.startDate')}
            endDate={get(location, 'state.endDate')}
            partners={get(location, 'state.partners')}
            productKey={get(location, 'state.productKey')}
            rating={get(location, 'state.rating')}
          />
        </Card>
        <Card className='overall-rating-card'>
          <OverallRating
            history={history}
            filterValues={filterValues}
          />
        </Card>
        <StatusWiseRating />
      </CustomerFeedbackStyle>
    )
  }
}

export default connect(state => ({
}), {
  getPartnersList,
  getProductsList,
  getFeedbackDashboardData
})(CustomerFeedback)
